(() => {
'use strict';
const key='bonga-fashion-flow-v1', stages=[['Design','Confirm brief, sketch, size range and quantity.'],['Fabric','Record fabric composition, swatch approval, metres needed and supplier quote.'],['Manufacturing','Confirm sample, fit, production quote, minimum order and lead time.'],['Packaging','Approve labels, care instructions, packaging and packed cost.'],['Marketing','Prepare images, offer, audience, launch date and sales channel.'],['Sale','Record customer agreement, final price and payment received.'],['Delivery','Record quality check, courier, tracking, dispatch and delivery proof.']];
const $=id=>document.getElementById(id);if(!$('fashion-project-form'))return;
let state={projects:[],contacts:[]};try{const v=JSON.parse(localStorage.getItem(key));if(v&&Array.isArray(v.projects)&&Array.isArray(v.contacts))state=v;}catch{}
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}, id=()=>crypto.randomUUID();
const safeURL=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}};
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('fashion-status').textContent='Saved on this device.';return true;}catch{$('fashion-status').textContent='Could not save. Export a backup before leaving.';return false;}}
function button(text,fn){const b=el('button',text);b.type='button';b.className='button secondary';b.onclick=fn;return b;}
function field(parent,title,value,change,type='text'){const l=el('label',title),n=el(type==='textarea'?'textarea':'input');if(type!=='textarea')n.type=type;n.value=value??'';n.onchange=()=>{change(n.value);save();};l.append(n);parent.append(l);return n;}
function render(){
const list=$('fashion-projects');list.replaceChildren();if(!state.projects.length)list.append(el('p','Start with a real design brief. No orders or sales have been assumed.'));
state.projects.forEach(p=>{const card=el('article');card.className='fashion-flow-card';card.append(el('h3',p.name),el('p',`${p.customer||'Customer / market not recorded'} · Target delivery: ${p.due||'Not set'}`));
const edit=el('details');edit.append(el('summary','Edit brief & brand direction'));field(edit,'Project name',p.name,v=>{p.name=v;render();});field(edit,'Design brief',p.brief,v=>p.brief=v,'textarea');field(edit,'Customer / market',p.customer,v=>p.customer=v);field(edit,'Delivery date',p.due,v=>p.due=v,'date');field(edit,'Brand promise',p.promise,v=>p.promise=v,'textarea');card.append(edit);
const strip=el('div');strip.className='fashion-stages';stages.forEach(([name,help],i)=>{const step=el('details');const record=p.steps[i]||{done:false,notes:'',partner:''};p.steps[i]=record;step.append(el('summary',`${record.done?'✓':'○'} ${name}`),el('p',help));const label=el('label'),check=el('input');check.type='checkbox';check.checked=record.done;check.onchange=()=>{record.done=check.checked;record.updated=new Date().toISOString();save();render();};label.append(check,document.createTextNode(' Confirmed complete'));step.append(label);
const partnerLabel=el('label','Network partner'),select=el('select');select.append(new Option('Not assigned',''));state.contacts.forEach(c=>select.append(new Option(`${c.name} · ${c.role}`,c.id)));select.value=record.partner;select.onchange=()=>{record.partner=select.value;save();};partnerLabel.append(select);step.append(partnerLabel);field(step,'Evidence / quote / progress notes',record.notes,v=>record.notes=v,'textarea');strip.append(step);});card.append(strip);
const completed=p.steps.filter(r=>r.done).length;
const next=p.steps.findIndex(r=>!r.done);
card.append(el('p',`${completed} of 7 stages confirmed · ${next<0?'All stages complete':'Next: '+stages[next][0]}`));
if(next>=0){
 const partner=state.contacts.find(c=>c.id===p.steps[next].partner);
 const taskModule=next===4?'marketing':next>=5?'sales':'products';
 const taskButton=button('Add next step to daily work',()=>{
  const input=$('import-plan'),form=$('import-form');
  if(!input||!form){$('fashion-status').textContent='Work queue unavailable. Reload your dashboard.';return;}
  input.value=JSON.stringify({tasks:[{id:'fashion-'+p.id+'-'+next,module:taskModule,title:(stages[next][0]+': '+p.name).slice(0,160),deliverable:(stages[next][1]+' '+(partner?'Partner: '+partner.name+'. ':'')+(p.steps[next].notes||'')).slice(0,500),minutes:30,priority:'high'}]});
  form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));
  $('fashion-status').textContent=$('import-status').textContent||'Check the daily work queue.';
 });card.append(taskButton);
}
const costs=el('details');costs.append(el('summary','Pricing & order record'));p.costs=p.costs||{};const result=el('p');const calc=()=>{const names=['fabric','making','packaging','delivery','other'];const complete=names.every(k=>Number.isFinite(p.costs[k]))&&Number.isFinite(p.costs.price);result.textContent=complete?`Recorded unit costs: R${names.reduce((a,k)=>a+p.costs[k],0).toFixed(2)} · Contribution before unrecorded expenses: R${(p.costs.price-names.reduce((a,k)=>a+p.costs[k],0)).toFixed(2)}`:'Contribution unknown — record all unit costs and selling price. Enter 0 only when confirmed.';};[['fabric','Fabric / unit'],['making','Manufacturing / unit'],['packaging','Packaging / unit'],['delivery','Delivery / unit'],['other','Other costs / unit'],['price','Selling price / unit']].forEach(([k,label])=>{const n=field(costs,label+' (ZAR)',p.costs[k],v=>{p.costs[k]=v===''?null:Number(v);calc();},'number');n.min='0';n.step='0.01';});field(costs,'Payment received (ZAR)',p.payment,v=>p.payment=v,'number');field(costs,'Courier tracking URL',p.tracking,v=>p.tracking=safeURL(v),'url');costs.append(result);calc();card.append(costs);
card.append(button('Prepare marketing & sales draft',()=>{const text=`Bonga Bhengu / DONLEGEND\n${p.name}\n${p.promise||'Add a confirmed brand promise.'}\n${p.brief||'Add the garment details.'}\nEnquire about fit, fabric and production availability.\n${Number.isFinite(p.costs.price)?'Recorded proposed unit price: R'+p.costs.price.toFixed(2)+' — confirm final quote.':'Price: quote required.'}\nDelivery timing subject to fabric, approved sample and production confirmation.`;draft.value=text;draft.hidden=false;}));const draft=el('textarea');draft.rows=8;draft.hidden=true;draft.setAttribute('aria-label','Editable marketing and sales draft');card.append(draft,button('Remove project',()=>{if(confirm('Remove this fashion project?')){state.projects=state.projects.filter(x=>x.id!==p.id);save();render();}}));list.append(card);});
const network=$('network-records');network.replaceChildren();if(!state.contacts.length)network.append(el('p','No network contacts saved yet. Add actual partners or research candidates.'));state.contacts.forEach(c=>{const card=el('article');card.className='fashion-flow-card';card.append(el('h3',c.name),el('p',`${c.role} · ${c.stage} · ${c.location||'Location unknown'}`),el('p',c.contact||'Contact not recorded'),el('p',c.notes));const url=safeURL(c.url);if(url){const a=el('a','Open evidence / website ↗');a.href=url;a.target='_blank';a.rel='noopener noreferrer';card.append(a);}card.append(button('Edit contact',()=>{const f=$('network-form');Object.keys(c).forEach(k=>{if(f.elements[k])f.elements[k].value=c[k];});f.scrollIntoView({behavior:'smooth'});}),button('Remove contact',()=>{if(confirm('Remove this network contact?')){state.contacts=state.contacts.filter(x=>x.id!==c.id);state.projects.forEach(p=>p.steps.forEach(r=>{if(r.partner===c.id)r.partner='';}));save();render();}}));network.append(card);});}
$('fashion-project-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.projects.push({id:id(),name:f.get('name'),brief:f.get('brief'),customer:f.get('customer'),promise:f.get('promise'),due:f.get('due'),steps:stages.map(()=>({done:false,notes:'',partner:''})),costs:{}});save();e.target.reset();render();};
$('network-form').onsubmit=e=>{e.preventDefault();const c=Object.fromEntries(new FormData(e.target));c.url=safeURL(c.url);c.id=c.id||id();const old=state.contacts.findIndex(x=>x.id===c.id);if(old>=0)state.contacts[old]=c;else state.contacts.push(c);save();e.target.reset();e.target.elements.id.value='';render();};
$('fashion-export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify({format:key,...state},null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='bonga-fashion-flow-network.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
$('fashion-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error();const v=JSON.parse(await file.text());if(v.format!==key||!Array.isArray(v.projects)||!Array.isArray(v.contacts)||v.projects.length>500||v.contacts.length>1000||!v.projects.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&Array.isArray(p.steps)&&p.steps.length===7&&p.steps.every(x=>x&&typeof x.notes==='string'))||!v.contacts.every(c=>typeof c.id==='string'&&typeof c.name==='string'))throw Error();if(!confirm('Replace current fashion flow and network with this backup?'))return;state={projects:v.projects,contacts:v.contacts};save();render();}catch{$('fashion-status').textContent='Backup not restored: invalid or oversized file.';}e.target.value='';};render();
})();
